import L520E from './l520e';
import { PowerUsage } from './powerUsage';
import { ColorLightSysinfo, ConsumptionInfo } from './types';

export default class L530 extends L520E {

  private _colorLightSysInfo!:ColorLightSysinfo;
  private _consumption!:ConsumptionInfo;

  constructor(
    public readonly log: any,
    public readonly ipAddress: string,
    public readonly email: string,
    public readonly password: string,
    public readonly timeout: number,
    port?: number,
    useHttps?: boolean,
  ) {
    super(log, ipAddress, email, password, timeout, port, useHttps);
    this.log.debug('Constructing L530 on host: ' + ipAddress);
    this._consumption = {
      total: 0,
      current: 0,
    };
  }

  async getDeviceInfo(force?:boolean): Promise<ColorLightSysinfo>{
    return super.getDeviceInfo(force).then(() => {
      return this.getSysInfo();
    });
  }

  async setColor(hue:number, saturation:number):Promise<boolean>{
    if(!hue){
      hue = 0;
    }
    if(!saturation){
      saturation = 0;
    }
    this.log.debug('Setting color: ' + hue + ', ' + saturation);
    const payload = '{'+
              '"method": "set_device_info",'+
              '"params": {'+
                  '"hue": ' + Math.round(hue) + ','+
                  '"color_temp": 0,' +
                  '"saturation": ' + Math.round(saturation) +
                  '},'+
                  '"requestTimeMils": ' + Math.round(Date.now() * 1000) + ''+
                  '};';

    return this.sendRequest(payload);
  }

  protected setSysInfo(sysInfo:ColorLightSysinfo){
    this._colorLightSysInfo = sysInfo;
    this._colorLightSysInfo.last_update = Date.now();
  }

  public getSysInfo():ColorLightSysinfo{
    return this._colorLightSysInfo;
  }

  async getEnergyUsage():Promise<PowerUsage>{
    this.log.debug('getEnergyUsage called');
    const response = await this.sendCommand('get_device_usage');
    this.log.debug('Consumption: ' + JSON.stringify(response));
    if(response && response.power_usage){
      this._consumption = {
        total: response.power_usage.today / 1000,
        current: this._consumption ? response.power_usage.today / this.toHours(response.time_usage.today) : 0,
      };
    } else{
      this._consumption = {
        total: 0,
        current: 0,
      };
    }
    return response;
  }

  public getPowerConsumption():ConsumptionInfo{
    if(!this.getSysInfo().device_on){
      return {
        total: this._consumption.total,
        current: 0,
      };
    }
    return this._consumption;
  }

  private toHours(minutes: number):number{
    return minutes/60;
  }

  /**
   * List the built-in dynamic light effect rules (with their ids/names) so the
   * effect id for setLightEffect (defined in P100) can be discovered.
   * Command from python-kasa LightEffectModule (get_dynamic_light_effect_rules).
   */
  async getLightEffects(): Promise<any> {
    return this.sendCommand('get_dynamic_light_effect_rules');
  }
}